#!/usr/bin/env python3
"""Render the four manual story-cost aliases from one project-owned source."""
import argparse
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def outputs():
    body = (ROOT / 'agent/spec-kit/story-cost.md').read_text()
    header = ('---\nname: story-cost\ndescription: Record this story\'s collected usage and cost.\n---\n'
              '<!-- Generated by agent/spec-kit/generate-entrypoints.py; edit its source. -->\n\n')
    return {**{ROOT / folder / 'skills/story-cost/SKILL.md': header + body
               for folder in ('.claude', '.agents', '.devin')},
            ROOT / '.opencode/commands/story-cost.md':
            '---\ndescription: Record this story\'s collected usage and cost.\n---\n'
            '<!-- Generated by agent/spec-kit/generate-entrypoints.py; edit its source. -->\n\n' + body}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    drift = []
    for path, text in outputs().items():
        if args.check:
            if not path.exists() or path.read_text() != text:
                drift.append(str(path.relative_to(ROOT)))
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text)
    if drift:
        parser.exit(1, 'story-cost entrypoint drift: ' + ', '.join(drift) + '\n')
    print('story-cost entrypoints: consistent')


if __name__ == '__main__':
    main()
